// RUAccent tokenizers (see ru_tokenizer.h).
//
// Verified against golden files generated by the reference Python tokenizers
// (tests/ru_tokenizer/gen_golden.py). Key behaviors (empirically confirmed):
//   * WordPiece (BERT/DistilBERT): BertPreTokenizer WITHOUT a leading space
//     (whitespace is its own pre-token); normalizer is a no-op for the
//     pipeline's pre-normalized input; a pre-token with no match -> [UNK] for
//     the whole pre-token; >100 codepoints -> [UNK].
//   * BPE (DeBERTa/omograph): GPT-2 ByteLevel pre-tokenizer WITH a leading
//     space (byte 0x20 -> U+0120 'Ġ'); GPT-2 bytes_to_unicode encoding;
//     added tokens (<w>, </w>, "к+оса"-style) matched whole before BPE;
//     RoBERTa pair post-processing <s> A </s> </s> B </s>.
#include "ru_tokenizer.h"

#include <algorithm>
#include <cctype>
#include <climits>
#include <fstream>
#include <sstream>

#include "ru_frontend.h"   // ru::utf8_decode / ru::utf8_encode

namespace ru {
namespace {

// ---------------------------------------------------------------------------
// UTF-8 + Unicode property helpers
// ---------------------------------------------------------------------------
bool utf8_cp_at(const std::string & s, size_t pos, uint32_t & cp, size_t & next) {
    if (pos >= s.size()) return false;
    auto v = utf8_decode(s.substr(pos, 8));
    if (v.empty()) return false;
    cp = v[0];
    next = pos + (v.size() > 0 ? utf8_encode(v).size() : 1);
    // compute the exact byte length of this single codepoint
    std::string one = utf8_encode({cp});
    next = pos + one.size();
    return true;
}

bool is_letter(uint32_t cp) {
    return (cp >= 0x41 && cp <= 0x5A) || (cp >= 0x61 && cp <= 0x7A) ||   // Latin
           (cp >= 0xC0 && cp <= 0x24F) ||                                  // Latin ext / Greek
           (cp >= 0x370 && cp <= 0x374) || (cp >= 0x376 && cp <= 0x377) ||
           (cp >= 0x37A && cp <= 0x37D) || (cp >= 0x37F && cp <= 0x3FF) ||
           (cp >= 0x400 && cp <= 0x4FF) || (cp >= 0x500 && cp <= 0x52F) || // Cyrillic
           (cp >= 0x1E00 && cp <= 0x1EFF);                                 // Latin ext add
}
bool is_number(uint32_t cp) {
    return (cp >= 0x30 && cp <= 0x39) || (cp >= 0x660 && cp <= 0x669) ||
           (cp >= 0x6F0 && cp <= 0x6F9);
}
bool is_space(uint32_t cp) {
    return cp == 0x20 || (cp >= 0x09 && cp <= 0x0D) || cp == 0x85 ||
           cp == 0xA0 || cp == 0x1680 || (cp >= 0x2000 && cp <= 0x200A) ||
           cp == 0x2028 || cp == 0x2029 || cp == 0x202F || cp == 0x205F ||
           cp == 0x3000;
}

std::string to_lower_utf8(const std::string & s) {
    auto cps = utf8_decode(s);
    for (auto & cp : cps) {
        if (cp >= 0x410 && cp <= 0x42F) cp += 0x30;   // A-Z (Cyrillic) -> a-z
        else if (cp >= 0x41 && cp <= 0x5A) cp += 0x20; // A-Z (Latin) -> a-z
    }
    return utf8_encode(cps);
}

int count_codepoints(const std::string & s) { return (int) utf8_decode(s).size(); }

// Map each byte position to its codepoint index (m[b] = #codepoints before byte b).
std::vector<int> build_byte_to_cp(const std::string & s) {
    std::vector<int> m(s.size() + 1, 0);
    int cp = 0;
    for (size_t i = 0; i < s.size();) {
        m[i] = cp;
        uint32_t c; size_t nx;
        utf8_cp_at(s, i, c, nx);
        i = nx;
        ++cp;
    }
    m[s.size()] = cp;
    return m;
}

// Load a vocab.txt (one token per line, id = line number).
bool load_vocab_txt(const std::string & path, std::unordered_map<std::string, int> & vocab) {
    std::ifstream f(path);
    if (!f) return false;
    std::string line;
    int id = 0;
    while (std::getline(f, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        vocab[line] = id++;
    }
    return true;
}

// ---------------------------------------------------------------------------
// WordPiece pre-tokenizer (BertPreTokenizer, NO leading space)
// ---------------------------------------------------------------------------
size_t wp_next_pre_token(const std::string & s, size_t pos) {
    // Apostrophe contractions first (rare in Russian, kept for parity).
    static const char * contr[] = {"'s", "'t", "'re", "'ve", "'m", "'ll", "'d"};
    for (auto c : contr) {
        size_t n = std::char_traits<char>::length(c);
        if (s.compare(pos, n, c) == 0) return pos + n;
    }
    uint32_t cp; size_t nx;
    if (!utf8_cp_at(s, pos, cp, nx)) return s.size();
    auto run = [&](bool (*pred)(uint32_t)) {
        size_t end = pos;
        uint32_t c; size_t n;
        while (end < s.size() && utf8_cp_at(s, end, c, n) && pred(c)) end = n;
        return end;
    };
    if (is_letter(cp)) return run(is_letter);
    if (is_number(cp)) return run(is_number);
    if (is_space(cp))  return run(is_space);
    // punctuation: a SINGLE char per pre-token (not a run)
    return nx;
}

// ---------------------------------------------------------------------------
// BPE (GPT-2 ByteLevel) pre-tokenizer (WITH leading space)
// ---------------------------------------------------------------------------
size_t bpe_next_pre_token(const std::string & s, size_t pos) {
    if (pos < s.size() && s[pos] == '\'') {
        size_t p = pos + 1;
        if (p + 1 < s.size()) {
            std::string two = s.substr(p, 2);
            if (two == "ll" || two == "ve" || two == "re") return p + 2;
        }
        if (p < s.size()) {
            char c = (char) std::tolower((unsigned char) s[p]);
            if (c == 's' || c == 'd' || c == 'm' || c == 't') return p + 1;
        }
        return pos + 1;
    }
    // Optional single leading space, then a letter/number/punct run.
    size_t p = pos;
    uint32_t cp; size_t nx;
    if (utf8_cp_at(s, p, cp, nx) && is_space(cp)) p = nx;
    if (p < s.size() && utf8_cp_at(s, p, cp, nx)) {
        auto run = [&](bool (*pred)(uint32_t)) {
            size_t end = p;
            uint32_t c; size_t n;
            while (end < s.size() && utf8_cp_at(s, end, c, n) && pred(c)) end = n;
            return end;
        };
        if (is_letter(cp)) return run(is_letter);
        if (is_number(cp)) return run(is_number);
        size_t end = p;
        uint32_t c; size_t n;
        while (end < s.size() && utf8_cp_at(s, end, c, n) &&
               !is_space(c) && !is_letter(c) && !is_number(c)) end = n;
        return end;
    }
    // Whitespace-only pre-token.
    size_t end = pos;
    uint32_t c; size_t n;
    while (end < s.size() && utf8_cp_at(s, end, c, n) && is_space(c)) end = n;
    return end;
}

// GPT-2 bytes_to_unicode table (byte -> codepoint).
std::vector<uint32_t> build_bytes_to_unicode() {
    std::vector<int> bs;
    for (int b = 33; b <= 126; ++b) bs.push_back(b);
    for (int b = 161; b <= 172; ++b) bs.push_back(b);
    for (int b = 174; b <= 255; ++b) bs.push_back(b);
    std::vector<int> cs = bs;
    int n = 0;
    for (int b = 0; b < 256; ++b) {
        if (std::find(bs.begin(), bs.end(), b) == bs.end()) {
            bs.push_back(b);
            cs.push_back(256 + n);
            ++n;
        }
    }
    std::vector<uint32_t> table(256, 0);
    for (size_t i = 0; i < bs.size(); ++i) table[bs[i]] = (uint32_t) cs[i];
    return table;
}

// Byte-encode a UTF-8 string into the GPT-2 byte-symbol string.
std::string byte_encode(const std::string & utf8_text, const std::vector<uint32_t> & table) {
    std::string out;
    out.reserve(utf8_text.size());
    for (unsigned char b : utf8_text) {
        out += ru::utf8_encode({table[b]});
    }
    return out;
}

}  // namespace

// ---------------------------------------------------------------------------
// CharTokenizer
// ---------------------------------------------------------------------------
bool CharTokenizer::load(const std::string & vocab_path) {
    return load_vocab_txt(vocab_path, vocab_);
}

TokOut CharTokenizer::tokenize(const std::string & text) const {
    TokOut out;
    std::string lower = to_lower_utf8(text);
    auto push = [&](int id) {
        out.input_ids.push_back(id);
        out.attention_mask.push_back(1);
        out.token_type_ids.push_back(0);
    };
    push(bos_);
    for (size_t pos = 0; pos < lower.size();) {
        uint32_t cp; size_t nx;
        utf8_cp_at(lower, pos, cp, nx);
        std::string ch = lower.substr(pos, nx - pos);
        auto it = vocab_.find(ch);
        push(it != vocab_.end() ? it->second : unk_);
        pos = nx;
    }
    push(eos_);
    return out;
}

// ---------------------------------------------------------------------------
// WordPieceTokenizer
// ---------------------------------------------------------------------------
bool WordPieceTokenizer::load(const std::string & vocab_path) {
    return load_vocab_txt(vocab_path, vocab_);
}

TokOut WordPieceTokenizer::tokenize(const std::string & text) const {
    TokOut out;
    std::vector<int> b2cp = build_byte_to_cp(text);
    auto cpos = [&](size_t byte_pos) { return b2cp[byte_pos]; };
    auto push = [&](int id, size_t os, size_t oe, int spec) {
        out.input_ids.push_back(id);
        out.attention_mask.push_back(1);
        out.token_type_ids.push_back(0);
        out.offsets.push_back({cpos(os), cpos(oe)});
        out.special_mask.push_back(spec);
    };
    push(cls_, 0, 0, 1);

    size_t pos = 0;
    while (pos < text.size()) {
        size_t end = wp_next_pre_token(text, pos);
        if (end <= pos) { end = pos + 1; }
        uint32_t cp; size_t nx;
        if (utf8_cp_at(text, pos, cp, nx) && !is_space(cp)) {
            std::string pre = text.substr(pos, end - pos);
            int ncp = count_codepoints(pre);
            if (ncp > max_chars_) {
                push(unk_, pos, end, 0);
            } else {
                bool beginning = true;
                size_t p = 0;
                while (p < pre.size()) {
                    bool matched = false;
                    for (size_t e = pre.size(); e > p; --e) {
                        std::string sub = pre.substr(p, e - p);
                        std::string lookup = beginning ? sub : ("##" + sub);
                        auto it = vocab_.find(lookup);
                        if (it != vocab_.end()) {
                            push(it->second, pos + p, pos + e, 0);
                            beginning = false;
                            p = e;
                            matched = true;
                            break;
                        }
                    }
                    if (!matched) { push(unk_, pos + p, end, 0); break; }
                }
            }
        }
        pos = end;
    }
    push(sep_, 0, 0, 1);
    return out;
}

// ---------------------------------------------------------------------------
// BPETokenizer
// ---------------------------------------------------------------------------
namespace {
bool is_json_ws(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r'; }

// Parse a JSON string starting at content[pos] (must be '"'). On success sets
// `out` to the unescaped string and advances `pos` past the closing quote.
bool parse_json_string(const std::string & content, size_t & pos, std::string & out) {
    if (pos >= content.size() || content[pos] != '"') return false;
    ++pos;
    while (pos < content.size()) {
        unsigned char c = (unsigned char) content[pos];
        if (c == '"') { ++pos; return true; }
        if (c == '\\') {
            ++pos;
            if (pos >= content.size()) return false;
            char e = content[pos];
            if (e == 'u') {
                if (pos + 4 >= content.size()) return false;
                uint32_t cp = (uint32_t) std::stoul(content.substr(pos + 1, 4), nullptr, 16);
                out += ru::utf8_encode({cp});
                pos += 5;
            } else {
                switch (e) {
                    case '"': out += '"'; break;
                    case '\\': out += '\\'; break;
                    case '/': out += '/'; break;
                    case 'b': out += '\b'; break;
                    case 'f': out += '\f'; break;
                    case 'n': out += '\n'; break;
                    case 'r': out += '\r'; break;
                    case 't': out += '\t'; break;
                    default: out += e; break;
                }
                ++pos;
            }
        } else {
            out += (char) c;
            ++pos;
        }
    }
    return false;
}

// Parse a flat JSON object of "string": int into `out`.
bool parse_flat_json(const std::string & content, std::unordered_map<std::string, int> & out) {
    size_t i = content.find('{');
    if (i == std::string::npos) return false;
    ++i;
    while (i < content.size()) {
        while (i < content.size() && (is_json_ws(content[i]) || content[i] == ',')) ++i;
        if (i >= content.size() || content[i] == '}') return true;
        if (content[i] != '"') return false;
        std::string key;
        if (!parse_json_string(content, i, key)) return false;
        while (i < content.size() && is_json_ws(content[i])) ++i;
        if (i >= content.size() || content[i] != ':') return false;
        ++i;
        while (i < content.size() && is_json_ws(content[i])) ++i;
        size_t num_start = i;
        if (i < content.size() && content[i] == '-') ++i;
        while (i < content.size() && isdigit((unsigned char) content[i])) ++i;
        if (i == num_start) return false;
        out[key] = std::stoi(content.substr(num_start, i - num_start));
    }
    return false;
}

std::string read_file(const std::string & path) {
    std::ifstream f(path);
    if (!f) return "";
    std::stringstream ss; ss << f.rdbuf();
    return ss.str();
}
}  // namespace

bool BPETokenizer::load(const std::string & dir) {
    // vocab.json
    {
        std::string content = read_file(dir + "/vocab.json");
        if (content.empty() || !parse_flat_json(content, vocab_)) return false;
    }
    // merges.txt
    {
        std::ifstream f(dir + "/merges.txt");
        if (!f) return false;
        std::string line;
        int rank = 0;
        bool first = true;
        while (std::getline(f, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (first) { first = false; if (!line.empty() && line[0] == '#') continue; }
            if (line.empty()) continue;
            size_t sp = line.find(' ');
            if (sp == std::string::npos) continue;
            std::string a = line.substr(0, sp);
            std::string b = line.substr(sp + 1);
            merge_ranks_[a + " " + b] = rank++;
        }
    }
    // added_tokens.json (optional)
    {
        std::string content = read_file(dir + "/added_tokens.json");
        if (!content.empty()) parse_flat_json(content, vocab_);
    }
    return true;
}

namespace {
// Greedily split `text` into segments; added tokens (longest first) become
// their own segments. Returns (is_added, content) pairs.
std::vector<std::pair<bool, std::string>> split_added(
        const std::string & text,
        const std::vector<std::pair<std::string, int>> & added_desc) {
    std::vector<std::pair<bool, std::string>> segs;
    std::string normal;
    auto flush = [&]() { if (!normal.empty()) { segs.push_back({false, normal}); normal.clear(); } };
    size_t pos = 0;
    while (pos < text.size()) {
        bool matched = false;
        for (auto & kv : added_desc) {
            const std::string & tok = kv.first;
            if (text.compare(pos, tok.size(), tok) == 0) {
                flush();
                segs.push_back({true, tok});
                pos += tok.size();
                matched = true;
                break;
            }
        }
        if (!matched) {
            uint32_t cp; size_t nx;
            utf8_cp_at(text, pos, cp, nx);
            normal += text.substr(pos, nx - pos);
            pos = nx;
        }
    }
    flush();
    return segs;
}
}  // namespace

TokOut BPETokenizer::tokenize_pair(const std::string & a, const std::string & b) const {
    static const std::vector<uint32_t> kTable = build_bytes_to_unicode();

    // added tokens sorted by length (desc) for greedy matching
    std::vector<std::pair<std::string, int>> added_desc;
    for (auto & kv : vocab_) {
        // added tokens are those not reachable by plain BPE; approximate by
        // tokens containing '<' or '+' (the ruaccent added-token shapes).
        if (kv.first.find('<') != std::string::npos ||
            kv.first.find('+') != std::string::npos) {
            added_desc.push_back(kv);
        }
    }
    std::sort(added_desc.begin(), added_desc.end(),
              [](const auto & x, const auto & y) { return x.first.size() > y.first.size(); });

    auto encode_one = [&](const std::string & text) {
        std::vector<int> ids;
        auto segs = split_added(text, added_desc);
        for (auto & seg : segs) {
            if (seg.first) {
                auto it = vocab_.find(seg.second);
                ids.push_back(it != vocab_.end() ? it->second : 3 /*<unk>*/);
            } else {
                size_t pos = 0;
                while (pos < seg.second.size()) {
                    size_t end = bpe_next_pre_token(seg.second, pos);
                    if (end <= pos) { end = pos + 1; }
                    std::string pre = seg.second.substr(pos, end - pos);
                    uint32_t cp; size_t nx;
                    if (utf8_cp_at(pre, 0, cp, nx) && is_space(cp)) {
                        // whitespace pre-token -> byte-encoded (space -> 'Ġ')
                        std::string be = byte_encode(pre, kTable);
                        // each space byte is a separate 'Ġ' symbol; BPE them
                        std::vector<std::string> syms;
                        for (size_t i = 0; i < be.size();) {
                            uint32_t c; size_t n;
                            utf8_cp_at(be, i, c, n);
                            syms.push_back(be.substr(i, n - i));
                            i = n;
                        }
                        // BPE merge
                        while (syms.size() > 1) {
                            int best = INT_MAX, bi = -1;
                            for (size_t i = 0; i + 1 < syms.size(); ++i) {
                                auto it = merge_ranks_.find(syms[i] + " " + syms[i + 1]);
                                if (it != merge_ranks_.end() && it->second < best) { best = it->second; bi = (int) i; }
                            }
                            if (bi < 0) break;
                            syms[bi] = syms[bi] + syms[bi + 1];
                            syms.erase(syms.begin() + bi + 1);
                        }
                        for (auto & s : syms) {
                            auto it = vocab_.find(s);
                            ids.push_back(it != vocab_.end() ? it->second : 3);
                        }
                    } else {
                        std::string be = byte_encode(pre, kTable);
                        std::vector<std::string> syms;
                        for (size_t i = 0; i < be.size();) {
                            uint32_t c; size_t n;
                            utf8_cp_at(be, i, c, n);
                            syms.push_back(be.substr(i, n - i));
                            i = n;
                        }
                        while (syms.size() > 1) {
                            int best = INT_MAX, bi = -1;
                            for (size_t i = 0; i + 1 < syms.size(); ++i) {
                                auto it = merge_ranks_.find(syms[i] + " " + syms[i + 1]);
                                if (it != merge_ranks_.end() && it->second < best) { best = it->second; bi = (int) i; }
                            }
                            if (bi < 0) break;
                            syms[bi] = syms[bi] + syms[bi + 1];
                            syms.erase(syms.begin() + bi + 1);
                        }
                        for (auto & s : syms) {
                            auto it = vocab_.find(s);
                            ids.push_back(it != vocab_.end() ? it->second : 3);
                        }
                    }
                    pos = end;
                }
            }
        }
        return ids;
    };

    TokOut out;
    auto A = encode_one(a);
    auto B = encode_one(b);
    out.input_ids.push_back(cls_);
    for (int id : A) out.input_ids.push_back(id);
    out.input_ids.push_back(sep_);
    out.input_ids.push_back(sep_);   // RoBERTa pair: two </s>
    for (int id : B) out.input_ids.push_back(id);
    out.input_ids.push_back(sep_);
    for (size_t i = 0; i < out.input_ids.size(); ++i) out.attention_mask.push_back(1);
    return out;
}

}  // namespace ru
